-- +goose Up
-- Banner kabupaten (backdrop, pelatihan teknis, seremoni, plakat).
-- regency_logos: logo kabupaten yang dicetak di kepala banner.
CREATE TABLE regency_logos (
    regency_id uuid PRIMARY KEY REFERENCES regencies(id) ON DELETE CASCADE,
    content bytea NOT NULL,
    mime_type text NOT NULL CHECK (mime_type IN ('image/png', 'image/jpeg')),
    original_filename text NOT NULL DEFAULT '',
    updated_by uuid REFERENCES users(id) ON DELETE SET NULL,
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Service center per kabupaten dan merk mesin, dari "Service Center Shark.xlsx"
-- (sheet shark dan loncin). Kunci kabupatennya nama huruf besar ("KAB. BONE"),
-- agar kabupaten yang ditambahkan belakangan tetap ketemu. Backdrop memakai
-- yang pertama (sort_order 1).
CREATE TABLE banner_service_centers (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    regency_name text NOT NULL,
    brand text NOT NULL CHECK (brand IN ('shark', 'loncin')),
    sort_order integer NOT NULL,
    name text NOT NULL,
    address text NOT NULL DEFAULT '',
    phone text NOT NULL DEFAULT '',
    owner text NOT NULL DEFAULT '',
    UNIQUE (regency_name, brand, sort_order)
);

-- Isian banner per jadwal. Service center kosong berarti memakai data master.
CREATE TABLE banner_settings (
    schedule_id uuid PRIMARY KEY REFERENCES program_schedules(id) ON DELETE CASCADE,
    service_center_name text,
    service_center_address text,
    service_center_phone text,
    seremoni_name text NOT NULL DEFAULT '',
    plakat_name text NOT NULL DEFAULT '',
    plakat_place text NOT NULL DEFAULT '',
    plakat_date date,
    updated_by uuid REFERENCES users(id) ON DELETE SET NULL,
    updated_at timestamptz NOT NULL DEFAULT now()
);


ON CONFLICT (code) DO NOTHING;

-- Siapa pun yang mengelola atau melihat Berita Acara mendapat akses banner yang setara.
SELECT rp.role_id, p.id FROM role_permissions rp
JOIN permissions src ON src.id = rp.permission_id
JOIN permissions p ON p.code = CASE src.code WHEN 'bast.manage' THEN 'banner.manage' WHEN 'bast.view' THEN 'banner.view' END
WHERE src.code IN ('bast.manage', 'bast.view')
ON CONFLICT DO NOTHING;

-- +goose Down
DELETE FROM permissions WHERE code IN ('banner.view', 'banner.manage');
DROP TABLE banner_settings;
DROP TABLE banner_service_centers;
DROP TABLE regency_logos;
